function atomicWriteFileSync(Cn,ei){return auxBrokerBoundary().sync(()=>{
 if(process.platform==='darwin'&&Cn===ACCOUNTS_JSON_PATH){
  const binding=process._linkedBinding('aux_owned_native');
  const descriptor=Object.getOwnPropertyDescriptor(binding,'validateMemoryRegistryTarget');
  if(!descriptor||typeof descriptor.value!=='function'||descriptor.writable||descriptor.configurable)
   throw Error('Native memory/account publication coordination is unavailable');
  Reflect.apply(descriptor.value,binding,[Buffer.from(ei,'utf8')]);
 }
 return auxAtomicWriteFileSyncBody(Cn,ei);
})}

